#![allow(unused_imports)]
use verus::prelude::*;

/// Multiply a polynomial by X, i.e. shift all coefficients
/// up by one degree (making room at the constant term).
#[verifier::decreases(c.len())]
#[verifier::ensures(result.len() == c.len() + 1)]
#[verifier::ensures(result[0] == 0.0)]
#[verifier::ensures(
    forall |i: usize| i < c.len() ==>
        result[i + 1] == c[i]
)]
fn polymulx(c: Vec<f32>) -> Vec<f32> {
    // Pre-allocate a new vector with one extra slot
    let mut result = Vec::with_capacity(c.len() + 1);
    // First element is 0.0
    result.push(0.0);
    // Copy all elements from the input in order
    for value in c {
        result.push(value);
    }
    result
}

